// Pure roster validation for the administrator campaign form. No roster data or credentials live here.
const text = (value) => String(value ?? '').trim();
const doctorCode = (primaryLocation) => text(primaryLocation).match(/\(([^)]+)\)\s*$/)?.[1] ?? '';

function buildCampaignRoster(locationRows, websiteRows, dentistRows, emailRows) {
  // These new locations are intentionally held out even if a URL appears in the sheet.
  const notLaunchedLocationCodes = new Set(['DFW-24', 'DFW-25']);
  const locations = [];
  const excludedLocations = [];
  const locationByCode = new Map();
  for (let index = 0; index < locationRows.length; index += 1) {
    const [rawCode, rawName, rawType] = locationRows[index] ?? [];
    const code = text(rawCode);
    if (!code) continue;
    const name = text(rawName);
    const type = text(rawType);
    const website = text(websiteRows[index]?.[0]);
    const reason = notLaunchedLocationCodes.has(code) ? 'not_launched'
      : /-(E|O|P)$/i.test(code) || type !== 'GD' ? 'specialty_or_nonpractice'
      : /test/i.test(`${code} ${name}`) ? 'test_location'
        : !website ? 'missing_website'
          : !/^[a-z0-9.-]+\.[a-z]{2,}(?:\/[^?#]*)?$/i.test(website) ? 'invalid_website'
            : null;
    if (reason) {
      excludedLocations.push({ code, name, reason });
      continue;
    }
    if (locationByCode.has(code)) throw new Error(`Duplicate location code: ${code}`);
    const location = { code, name, public_website_url: `https://${website.replace(/\/$/, '').toLowerCase()}` };
    locationByCode.set(code, location);
    locations.push(location);
  }

  const doctors = [];
  const excludedDoctors = [];
  const seenEmails = new Set();
  for (let index = 0; index < dentistRows.length; index += 1) {
    const [rawName, rawPrimary, rawDepartment, rawEmployment] = dentistRows[index] ?? [];
    const name = text(rawName);
    if (!name) continue;
    const primary = text(rawPrimary);
    const code = doctorCode(primary);
    const department = text(rawDepartment);
    const employment = text(rawEmployment);
    const email = text(emailRows[index]?.[0]).toLowerCase();
    const reason = department !== 'General Dentist' ? 'not_general_dentist'
      : !['Full-Time', 'Part-Time'].includes(employment) ? 'not_employee'
        : /test/i.test(primary) || code === 'DFW-T' ? 'test_location'
          : !locationByCode.has(code) ? 'location_unavailable'
            : !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? 'missing_or_invalid_work_email'
              : null;
    if (reason) {
      excludedDoctors.push({ name, code, reason });
      continue;
    }
    if (seenEmails.has(email)) throw new Error(`Duplicate work email in census: ${email}`);
    seenEmails.add(email);
    doctors.push({ name, email, location_code: code });
  }
  return { locations, doctors, excludedLocations, excludedDoctors };
}

const rows = (nodeName, columns) => {
  const observed = $(nodeName).first().json.rows;
  const result = [];
  for (const row of observed) {
    const index = Number(row.row_number) - 2;
    if (!Number.isInteger(index) || index < 0) throw new Error('Unexpected Sheet row number in ' + nodeName);
    result[index] = columns.map((column) => row[column] ?? '');
  }
  return result;
};
const roster = buildCampaignRoster(
  rows('Keep location rows together', ['Code', 'Name', 'Type']),
  rows('Keep website rows together', ['URL']),
  rows('Keep dentist rows together', ['Employee', 'Primary Location', 'Department', 'Employment Type']),
  rows('Read dentist work emails', ['Work Email'])
);
if (!roster.locations.length || !roster.doctors.length) throw new Error('No eligible locations or dentists. Check Sheet access and headers.');
return [{ json: roster }];

const roster = $('Validate current roster').first().json;
const raw = $input.first().json.selected_locations;
const selections = Array.isArray(raw) ? raw : raw ? [raw] : [];
const byLabel = new Map(roster.locations.map((x) => [x.code + ' — ' + x.name, x.code]));
const codes = selections.map((label) => {
  const code = byLabel.get(label);
  if (!code) throw new Error('Unknown location selection: ' + label);
  return code;
});
if (!codes.length) throw new Error('Select at least one location.');
const chosen = new Set(codes);
const doctors = roster.doctors.filter((x) => chosen.has(x.location_code));
if (!doctors.length) throw new Error('No eligible dentists at the selected locations.');
return [{ json: { locations: roster.locations.filter((x) => chosen.has(x.code)), doctors } }];

const available = $('Filter doctors by selected locations').first().json;
const raw = $input.first().json.selected_doctors;
const selections = Array.isArray(raw) ? raw : raw ? [raw] : [];
const byLabel = new Map(available.doctors.map((x) => [x.name + ' (' + x.location_code + ') — ' + x.email, x]));
const doctors = selections.map((label) => {
  const doctor = byLabel.get(label);
  if (!doctor) throw new Error('Unknown dentist selection: ' + label);
  return doctor;
});
if (!doctors.length || new Set(doctors.map((x) => x.email)).size !== doctors.length) throw new Error('Select at least one distinct dentist.');
const details = $('Start selection preview').first().json;
return [{ json: { preview_only: true, campaign_name: details.campaign_name, campaign_month: details.campaign_month, topics: [details.topic_1, details.topic_2, details.topic_3], location_count: available.locations.length, doctor_count: doctors.length, locations: available.locations, doctors, message: 'Preview only: no campaign, invitations, WordPress posts, or static-site release created.' } }];
